package com.mercado.controller;
import com.mercado.repository.*;import com.mercado.model.Enums.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;
@Controller @RequestMapping("/relatorios") public class RelatorioController {
 private final VendaRepository v;private final ProdutoRepository p;public RelatorioController(VendaRepository v,ProdutoRepository p){this.v=v;this.p=p;}
 @GetMapping public String index(Model m){var vendas=v.findAllComItens().stream().filter(x->x.getStatus()==StatusVenda.CONCLUIDA).toList();BigDecimal faturamento=vendas.stream().map(x->x.getValorTotal()).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal custo=vendas.stream().flatMap(x->x.getItens().stream()).map(i->i.getPrecoCustoUnitario().multiply(BigDecimal.valueOf(i.getQuantidade()))).reduce(BigDecimal.ZERO,BigDecimal::add);m.addAttribute("faturamento",faturamento);m.addAttribute("custo",custo);m.addAttribute("lucro",faturamento.subtract(custo));m.addAttribute("vendas",vendas);m.addAttribute("produtos",p.findAll());return "relatorios";}
 @GetMapping("/vendas.csv") @ResponseBody public org.springframework.http.ResponseEntity<String> csv(){StringBuilder b=new StringBuilder("id,data,forma_pagamento,status,total\n");v.findAll().forEach(x->b.append(x.getId()).append(',').append(x.getDataVenda()).append(',').append(x.getFormaPagamento()).append(',').append(x.getStatus()).append(',').append(x.getValorTotal()).append('\n'));return org.springframework.http.ResponseEntity.ok().header("Content-Disposition","attachment; filename=vendas.csv").header("Content-Type","text/csv; charset=UTF-8").body("\uFEFF"+b);}
}
